package game.agent;
import game.agent.web.AgentWebServer;import game.agent.web.ProviderSelection;import java.net.*;import java.io.*;import java.util.*;import java.nio.charset.StandardCharsets;import org.junit.jupiter.api.Test;import static org.junit.jupiter.api.Assertions.*;
class PhaserAssetTest {
 @Test void packagedPhaserAndBinaryArtAreServedOfflineWithCorrectTypes()throws Exception{
  try(AgentWebServer s=new AgentWebServer(0,ProviderSelection.fromEnvironment(Collections.emptyMap()),null,true,null)){s.start();String root="http://127.0.0.1:"+s.getPort();for(String path:Arrays.asList("/rpg/vendor/phaser-3.60.0.min.js","/rpg/assets/images/monster-tamer/monsters/aquavalor.png","/rpg/assets/images/monster-tamer/map/main_1_level_background.png","/quest/rpg-view.mjs","/training/rpg-scene.mjs","/map-polish.mjs","/quest/map-polish.mjs","/training/map-polish.mjs","/growth/map-polish.mjs")){HttpURLConnection c=(HttpURLConnection)new URL(root+path).openConnection();assertEquals(200,c.getResponseCode(),path);assertTrue(c.getHeaderField("Content-Type").startsWith(path.endsWith(".png")?"image/png":"text/javascript"));try(InputStream in=c.getInputStream()){byte[] bytes=new byte[8];assertEquals(8,in.read(bytes));if(path.endsWith(".png"))assertEquals((byte)137,bytes[0]);}assertTrue(c.getHeaderField("Content-Security-Policy").contains("script-src 'self'"));assertTrue(c.getHeaderField("Content-Security-Policy").contains("img-src 'self' data: blob:"));}for(String path:Arrays.asList("/rpg/assets/unknown.png","/rpg/../pom.xml","/rpg/vendor/../../README.md")){assertEquals(404,((HttpURLConnection)new URL(root+path).openConnection()).getResponseCode());}}
 }
}
